//! Deterministic generators of large inputs for spikes and benchmarks.

/// A believable Rust source file of exactly `lines` lines.
pub fn rust_source(lines: usize) -> String {
    let mut out = String::with_capacity(lines * 48);
    let mut written = 0;
    let mut item = 0usize;
    let push = |out: &mut String, line: &str, written: &mut usize| {
        if *written < lines {
            out.push_str(line);
            out.push('\n');
            *written += 1;
        }
    };
    push(
        &mut out,
        "//! Generated by ferro_perf for editor benchmarks.",
        &mut written,
    );
    push(&mut out, "use std::collections::HashMap;", &mut written);
    while written < lines {
        let n = item;
        item += 1;
        push(&mut out, "", &mut written);
        push(
            &mut out,
            &format!("/// Computes value number {n}."),
            &mut written,
        );
        push(
            &mut out,
            &format!("pub fn compute_{n}(input: &HashMap<String, u64>) -> u64 {{"),
            &mut written,
        );
        push(
            &mut out,
            &format!("    let key = \"key_{n}\".to_string();"),
            &mut written,
        );
        push(
            &mut out,
            &format!(
                "    let base = input.get(&key).copied().unwrap_or({});",
                n % 97
            ),
            &mut written,
        );
        push(
            &mut out,
            &format!("    if base > {} {{", n % 13),
            &mut written,
        );
        push(
            &mut out,
            &format!("        base.wrapping_mul({}) ^ 0x{:x}", n % 31 + 1, n),
            &mut written,
        );
        push(&mut out, "    } else {", &mut written);
        push(&mut out, "        base + 1 // keep it simple", &mut written);
        push(&mut out, "    }", &mut written);
        push(&mut out, "}", &mut written);
    }
    out
}

#[cfg(test)]
mod tests {
    #[test]
    fn rust_source_has_the_requested_number_of_lines() {
        for lines in [1, 2, 10, 1000, 100_000] {
            assert_eq!(super::rust_source(lines).lines().count(), lines);
        }
    }
}
